use windows_sys::Win32::System::Memory::{VirtualAlloc, MEM_COMMIT, MEM_RESERVE, PAGE_EXECUTE_READWRITE};

fn allocate_rwx(size: usize) -> *mut std::ffi::c_void {
    // We must use unsafe when calling raw Windows API functions
    unsafe {
        // VirtualAlloc asks the OS kernel for memory
        let addr = VirtualAlloc(
            ptr::null(),              // Let the OS pick the memory location
            size,                     // Size of our shellcode
            MEM_COMMIT | MEM_RESERVE, // Allocate and reserve the physical pages
            PAGE_EXECUTE_READWRITE    // RWX: Read, Write, and Execute permissions
        );

        return addr;
    }
}

